<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { ElMessage,ElMessageBox } from 'element-plus';
import { ArrowLeft, Download, Plus, RefreshCw, Search, ShieldCheck } from 'lucide-vue-next';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import { binary,fail,params,permission,sf,sl,statusTone } from '../safety-workspace';
import { saveBlob } from '../admission';
import { number,label } from '../province-monitoring';
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ProvinceMonitoringMap from '../components/ProvinceMonitoringMap.vue';
import AccidentVideoPlayer from '../components/AccidentVideoPlayer.vue';
import EvidenceTimeline from '../components/EvidenceTimeline.vue';
import MonitoringRuleEvidence from '../components/MonitoringRuleEvidence.vue';
import SafetyTaskEditor from '../components/SafetyTaskEditor.vue';
import SafetyTaskDrawer from '../components/SafetyTaskDrawer.vue';
import SafetyMaterials from '../components/SafetyMaterials.vue';
import '../subject-management.css';
import '../province-monitoring.css';
import '../safety-workspace.css';
const route=useRoute(),router=useRouter(),session=useSessionStore(),filters=reactive({q:'',eventType:'',queue:'',range:null as [string,string]|null});
const rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref(''),options=ref<any>({vehicles:[],enterprises:[],eventTypes:[]}),optionsError=ref('');
const selected=ref({kind:'',id:''}),detail=ref<any>(),detailLoading=ref(false),detailError=ref(''),tab=ref('evidence'),cursor=ref(0),playing=ref(false),speed=ref(1),revision=ref<number|undefined>(),actionBusy=ref(false),exporting=ref(false),mobileSelection=ref(false);
const editor=ref(false),editorSaving=ref(false),editorError=ref(''),taskEditor=ref(false),taskDefault=ref('EMERGENCY'),taskOpen=ref(false),taskId=ref(''),taskType=ref(''),videoDialog=ref(false),videoBusy=ref(false),videoError=ref(''),videoFiles=ref<any[]>([]),uploading=ref(false),determinationDialog=ref(false),determinationFiles=ref<any[]>([]),determinationError=ref('');
const eventForm=reactive({kind:'ACCIDENT',vehicleId:'',title:'',description:'',accidentType:'COLLISION',alertType:'MANUAL_REPORT',level:'MEDIUM',occurredAt:'',longitude:undefined as number|undefined,latitude:undefined as number|undefined,address:'',casualties:0});
const videoForm=reactive({mode:'upload',name:'',channel:'FRONT',url:'',startedAt:'',endedAt:'',source:''}),determinationForm=reactive({authority:'',documentNo:'',issuedAt:'',result:''});
let listGeneration=0,detailGeneration=0,navGeneration=0,listController:AbortController|undefined,detailController:AbortController|undefined,listKey='',editorInitial='',videoInitial='',determinationInitial='';
const enterprise=computed(()=>session.user?.portal==='ENTERPRISE'),canRegister=computed(()=>permission(session.user,'safety:accident:report')||permission(session.user,'safety:alert:write'));
const writePermission:Record<string,string>={ALERT:'safety:alert:handle',ACCIDENT:'safety:accident:handle',VIOLATION:'safety:violation:review',OFFLINE:'safety:offline:handle'};
const canHandle=computed(()=>!enterprise.value&&permission(session.user,writePermission[selected.value.kind]??''));
const canVideo=computed(()=>!revision.value&&['ACCIDENT','ALERT'].includes(selected.value.kind)&&permission(session.user,selected.value.kind==='ACCIDENT'?'safety:accident:report':'safety:alert:write'));
const from=computed(()=>Date.parse(detail.value?.window.from)||0),to=computed(()=>Date.parse(detail.value?.window.to)||0),t0=computed(()=>Date.parse(detail.value?.occurredAt)||0);
const currentFix=computed(()=>{const points=detail.value?.track??[];if(!points.length)return null;const point=points.reduce((a:any,b:any)=>Math.abs(Date.parse(a.recordedAt)-cursor.value)<Math.abs(Date.parse(b.recordedAt)-cursor.value)?a:b);return Math.abs(Date.parse(point.recordedAt)-cursor.value)<=5000?point:null});
const keyEvents=computed(()=>detail.value?[...(detail.value.alerts??[]).map((a:any)=>({...a,type:'ALERT'})),{id:detail.value.eventId,title:detail.value.title,occurredAt:detail.value.occurredAt,type:detail.value.eventType}].filter((v,i,a)=>a.findIndex(s=>s.id===v.id)===i).sort((a,b)=>Date.parse(a.occurredAt)-Date.parse(b.occurredAt)):[]);
const nextAction=computed(()=>{if(!canHandle.value||!detail.value)return null;const state=detail.value.status;const maps:Record<string,Record<string,string>>={ACCIDENT:{REPORTED:'ACCEPT',ACCEPTED:'INVESTIGATE',INVESTIGATING:'DETERMINE',RESPONSIBILITY_DETERMINED:'PROCESS',PROCESSING:'CLOSE',CLOSED:'ARCHIVE'},ALERT:{PENDING_CONFIRMATION:'CONFIRM',PENDING_HANDLING:'START',IN_PROGRESS:'SUBMIT_REVIEW',PENDING_REVIEW:'CLOSE',CLOSED:'REOPEN'},VIOLATION:{PENDING_DETERMINATION:'CONFIRM',PENDING_REVIEW:'APPROVE'},OFFLINE:{OFFLINE:'INVESTIGATE',INVESTIGATING:'RECOVER'}};return maps[selected.value.kind]?.[state]??null});
const caseActionLabel=(a:string)=>a==='CLOSE'?'办结事件':a==='DETERMINE'?'登记认定结果':sl(a);
function listValues(){return {q:filters.q.trim(),eventType:filters.eventType,queue:filters.queue,from:filters.range?.[0],to:filters.range?.[1],vehicleId:route.query.vehicleId,page:page.value,pageSize:8}}
async function loadOptions(){optionsError.value='';try{options.value=await api('/safety/workspace/options')}catch(e){optionsError.value=fail(e)}}
async function loadList(){const g=++listGeneration;listController?.abort();listController=new AbortController();loading.value=true;error.value='';try{const data=await api<any>(`/safety/workspace/events?${params(listValues())}`,{signal:listController.signal});if(g!==listGeneration)return;rows.value=data.items;total.value=data.total}catch(e){if(g===listGeneration&&!listController.signal.aborted)error.value=fail(e)}finally{if(g===listGeneration)loading.value=false}}
async function loadDetail(preserveCursor=false){const g=++detailGeneration;detailController?.abort();detailController=new AbortController();playing.value=false;detailError.value='';const oldCursor=cursor.value;if(!preserveCursor)detail.value=undefined;if(!selected.value.id)return;detailLoading.value=true;try{const data=await api<any>(`/safety/workspace/events/${selected.value.kind}/${selected.value.id}?${params({revision:revision.value})}`,{signal:detailController.signal});if(g!==detailGeneration)return;detail.value=data;cursor.value=preserveCursor?Math.max(Date.parse(data.window.from),Math.min(Date.parse(data.window.to),oldCursor)):Date.parse(data.window.from)}catch(e){if(g===detailGeneration&&!detailController.signal.aborted)detailError.value=fail(e)}finally{if(g===detailGeneration)detailLoading.value=false}}
function search(reset=true){if(reset)page.value=1;const query={...Object.fromEntries(params({...listValues(),pageSize:undefined})),eventKind:undefined,eventId:undefined,view:undefined,accidentId:undefined};if(router.resolve({path:route.path,query}).fullPath===route.fullPath){void loadList().then(()=>{selected.value={kind:rows.value[0]?.kind??'',id:rows.value[0]?.id??''};revision.value=undefined;void loadDetail()})}else void router.replace({path:route.path,query})}
function reset(){Object.assign(filters,{q:'',eventType:'',queue:'',range:null});page.value=1;void router.replace({path:route.path,query:{}});if(!route.fullPath.includes('?'))void loadList()}
function choose(row:any){mobileSelection.value=true;void router.replace({path:route.path,query:{...route.query,eventKind:row.kind,eventId:row.id,view:undefined,accidentId:undefined}})}
async function refresh(){await loadList();if(selected.value.id)await loadDetail(true)}
async function act(){const action=nextAction.value;if(!action)return;if(action==='DETERMINE'){Object.assign(determinationForm,{authority:'',documentNo:'',issuedAt:'',result:''});determinationFiles.value=[];determinationError.value='';determinationInitial=JSON.stringify(determinationForm);determinationDialog.value=true;return;}let comment='';try{comment=(await ElMessageBox.prompt('填写本次办理意见，内容将保留在处置记录中。',caseActionLabel(action),{inputType:'textarea',inputValidator:(v:string)=>v?.trim()?true:'请填写办理意见'})).value}catch{return}actionBusy.value=true;try{const endpoint=({ACCIDENT:'accidents',ALERT:'alerts',VIOLATION:'violations',OFFLINE:'offline-events'} as any)[selected.value.kind];await api(`/safety/${endpoint}/${selected.value.id}/actions`,{method:'POST',body:JSON.stringify({action,comment})});ElMessage.success('处置记录已更新');await refresh()}catch(e){ElMessage.error(fail(e))}finally{actionBusy.value=false}}
async function offlineReason(){let comment='';try{comment=(await ElMessageBox.prompt('填写排查得到的离线原因。','补充离线原因',{inputType:'textarea',inputValidator:(v:string)=>v?.trim()?true:'请填写原因'})).value}catch{return}try{await api(`/safety/offline-events/${selected.value.id}/actions`,{method:'POST',body:JSON.stringify({action:'UPDATE_REASON',comment})});await loadDetail(true)}catch(e){ElMessage.error(fail(e))}}
async function preserve(){let reason='';try{reason=(await ElMessageBox.prompt('将当前窗口的轨迹、录像索引及状态保存为新版本；补传后可再次保全，原版本保留。请填写说明。','保全证据',{inputType:'textarea',inputValidator:(v:string)=>v?.trim()?true:'请填写保全说明'})).value}catch{return}actionBusy.value=true;try{const r=await api<any>(`/safety/workspace/events/${selected.value.kind}/${selected.value.id}/preserve`,{method:'POST',body:JSON.stringify({reason})});ElMessage.success(`已保全证据版本V${r.version}`);await loadDetail(true)}catch(e){ElMessage.error(fail(e))}finally{actionBusy.value=false}}
async function exportEvidence(){exporting.value=true;try{saveBlob(await binary(`/safety/workspace/events/${selected.value.kind}/${selected.value.id}/export?${params({revision:revision.value})}`),`${detail.value.businessNo}-证据${revision.value?'-V'+revision.value:''}.zip`)}catch(e){ElMessage.error(fail(e))}finally{exporting.value=false}}
function newTask(type='EMERGENCY'){taskDefault.value=type;taskEditor.value=true;playing.value=false}
function openTask(task:any){taskId.value=task.id;taskType.value=task.taskType;taskOpen.value=true;playing.value=false}
async function taskCreated(task:any){openTask(task);await loadDetail(true)}
function openEditor(){Object.assign(eventForm,{kind:permission(session.user,'safety:accident:report')?'ACCIDENT':'ALERT',vehicleId:'',title:'',description:'',accidentType:'COLLISION',alertType:'MANUAL_REPORT',level:'MEDIUM',occurredAt:'',longitude:undefined,latitude:undefined,address:'',casualties:0});editorInitial=JSON.stringify(eventForm);editorError.value='';editor.value=true}
function lastLocation(){const v=options.value.vehicles.find((v:any)=>v.id===eventForm.vehicleId);if(!v?.realtimeStatus)return ElMessage.warning('该车辆暂无上报位置，请填写核实后的事发坐标');eventForm.longitude=v.realtimeStatus.longitude;eventForm.latitude=v.realtimeStatus.latitude;ElMessage.info(`已引用最后上报位置（${sf(v.realtimeStatus.locationTime)}），请核对事发位置`)}
async function saveEvent(){if(!eventForm.vehicleId||!eventForm.title.trim()||!eventForm.occurredAt||eventForm.longitude==null||eventForm.latitude==null||!eventForm.description.trim())return ElMessage.warning('请填写车辆、事件名称、发生时间、位置和经过');editorSaving.value=true;editorError.value='';try{const {kind,accidentType,alertType,casualties,...base}=eventForm;const data=await api<any>(kind==='ACCIDENT'?'/safety/accidents':'/safety/alerts',{method:'POST',body:JSON.stringify({...base,occurredAt:new Date(base.occurredAt).toISOString(),...(kind==='ACCIDENT'?{accidentType,casualties}:{alertType})})});editorInitial=JSON.stringify(eventForm);editor.value=false;ElMessage.success('事件已登记');await loadList();choose({id:data.id,kind})}catch(e){editorError.value=fail(e)}finally{editorSaving.value=false}}
async function confirmClose(name:'event'|'video'|'determination'){if(editorSaving.value||videoBusy.value||uploading.value)return;const dirty=name==='event'?JSON.stringify(eventForm)!==editorInitial:name==='video'?JSON.stringify(videoForm)!==videoInitial||videoFiles.value.length>0:JSON.stringify(determinationForm)!==determinationInitial||determinationFiles.value.length>0;if(dirty){try{await ElMessageBox.confirm('尚有未提交内容，是否放弃本次填写？','放弃未提交内容',{confirmButtonText:'放弃改动',cancelButtonText:'继续填写'})}catch{return}}if(name==='event')editor.value=false;else if(name==='video')videoDialog.value=false;else determinationDialog.value=false}
function openVideo(){Object.assign(videoForm,{mode:'upload',name:'',channel:'FRONT',url:'',startedAt:detail.value.window.from,endedAt:detail.value.window.to,source:''});videoFiles.value=[];videoInitial=JSON.stringify(videoForm);videoError.value='';videoDialog.value=true;playing.value=false}
async function submitVideo(){const material=videoFiles.value[0],url=videoForm.mode==='upload'?material?.url:videoForm.url;if(!url||!videoForm.startedAt||!videoForm.endedAt)return ElMessage.warning('请上传录像或填写来源地址，并填写真实录像起止时间');videoBusy.value=true;videoError.value='';try{await api(`/safety/workspace/events/${selected.value.kind}/${selected.value.id}/videos`,{method:'POST',body:JSON.stringify({videos:[{name:videoForm.name||material?.name||'关联录像',channel:videoForm.channel,url,startedAt:new Date(videoForm.startedAt).toISOString(),endedAt:new Date(videoForm.endedAt).toISOString(),source:videoForm.source}]})});videoDialog.value=false;ElMessage.success('录像已关联');await refresh()}catch(e){videoError.value=fail(e)}finally{videoBusy.value=false}}
async function submitDetermination(){if(!determinationForm.authority.trim()||!determinationForm.documentNo.trim()||!determinationForm.issuedAt||!determinationForm.result.trim()||!determinationFiles.value.length)return ElMessage.warning('请填写认定机关、文号、出具时间、结果并上传文书');videoBusy.value=true;determinationError.value='';try{await api(`/safety/workspace/accidents/${selected.value.id}/determination`,{method:'POST',body:JSON.stringify({...determinationForm,issuedAt:new Date(determinationForm.issuedAt).toISOString(),materialIds:determinationFiles.value.map(f=>f.id)})});determinationDialog.value=false;ElMessage.success('认定结果已登记');await refresh()}catch(e){determinationError.value=fail(e)}finally{videoBusy.value=false}}
watch(()=>route.query,async query=>{const n=++navGeneration;filters.q=String(query.q??'');filters.eventType=String(query.eventType??(['ALERT','ACCIDENT','VIOLATION','OFFLINE'].includes(String(query.view))?query.view:''));filters.queue=String(query.queue??'');filters.range=query.from&&query.to?[String(query.from),String(query.to)]:null;page.value=Math.max(1,Number(query.page)||1);const key=String(params(listValues()));if(key!==listKey){listKey=key;await loadList()}if(n!==navGeneration)return;const kind=String(query.eventKind??(query.accidentId?'ACCIDENT':query.view??rows.value[0]?.kind??'')),id=String(query.eventId??query.accidentId??rows.value[0]?.id??'');if(selected.value.id!==id||selected.value.kind!==kind||!detail.value){selected.value={kind,id};revision.value=undefined;tab.value='evidence';if(query.eventId||query.accidentId)mobileSelection.value=true;void loadDetail()}},{immediate:true});
void loadOptions();onBeforeUnmount(()=>{listGeneration++;detailGeneration++;navGeneration++;listController?.abort();detailController?.abort();playing.value=false});
</script>
<template><section class="city-subject-page safety-workspace-page safety-events"><h1 class="sr-only">事件处置</h1><QueryPanel class="subject-query" :loading="loading" @search="search()" @reset="reset"><QueryField label="关键词" keyword><el-input v-model="filters.q" aria-label="搜索安全事件" :prefix-icon="Search" clearable placeholder="搜索事件编号、车辆或企业"/></QueryField><QueryField label="事件类型"><el-select v-model="filters.eventType" aria-label="事件类型" clearable placeholder="全部类型"><el-option v-for="kind in options.eventTypes" :key="kind" :label="sl(kind)" :value="kind"/></el-select></QueryField><QueryField label="处置状态"><el-select v-model="filters.queue" aria-label="处置状态" clearable placeholder="全部状态"><el-option label="待处置" value="PENDING"/><el-option label="办理中" value="HANDLING"/><el-option label="待复核" value="REVIEW"/><el-option label="已办结" value="CLOSED"/></el-select></QueryField><QueryField label="发生时间" wide><el-date-picker v-model="filters.range" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="事件发生时间范围"/></QueryField></QueryPanel><section class="safety-surface"><header class="safety-header"><h2>事件处置<span class="subject-count">{{total}}</span></h2><div><el-button :icon="RefreshCw" :loading="loading" @click="refresh">刷新</el-button><el-button v-if="canRegister" :icon="Plus" type="primary" @click="openEditor">登记事件</el-button></div></header><div v-if="error" class="safety-error"><strong>事件列表暂时无法读取</strong><span>{{error}}</span><el-button @click="loadList">重试</el-button></div><div v-else class="safety-event-grid" :class="{'has-selection':mobileSelection}"><aside class="safety-event-rail" aria-label="事件记录"><div class="safety-tabs" style="padding-inline:12px"><button type="button" :aria-pressed="!filters.queue" @click="filters.queue='';search()">全部事件</button><button type="button" :aria-pressed="filters.queue==='PENDING'" @click="filters.queue='PENDING';search()">待处置</button></div><div v-loading="loading" class="safety-rail-rows"><button v-for="row in rows" :key="`${row.kind}:${row.id}`" type="button" class="safety-event-row" :aria-pressed="selected.id===row.id&&selected.kind===row.kind" @click="choose(row)"><div><strong>{{row.title}}</strong><el-tag size="small" :type="statusTone(row.status)">{{sl(row.status)}}</el-tag></div><small>{{sl(row.kind)}} · {{row.businessNo}}</small><small>{{row.vehicle?.name||'平台事项'}}</small><small>{{sf(row.occurredAt)}}</small><small v-if="['ACCIDENT','ALERT'].includes(row.kind)">{{row.videoCount?`已关联${row.videoCount}段录像`:'录像待补传'}}</small></button><el-empty v-if="!loading&&!rows.length" description="暂无符合条件的事件" :image-size="60"/></div><el-pagination v-model:current-page="page" small :total="total" :page-size="8" :pager-count="5" layout="prev,pager,next" @current-change="search(false)"/></aside><main class="safety-case" v-loading="detailLoading"><el-button class="safety-mobile-back" :icon="ArrowLeft" @click="mobileSelection=false">事件列表</el-button><div v-if="detailError" class="safety-error"><strong>事件详情暂时无法读取</strong><span>{{detailError}}</span><el-button @click="loadDetail()">重试</el-button></div><template v-else-if="detail"><header class="safety-case-identity"><div><h3>{{detail.title}}<el-tag size="small" :type="statusTone(detail.status)">{{sl(detail.status)}}</el-tag></h3><p>{{detail.businessNo}} · {{detail.vehicle?.name||'平台事项'}} · {{detail.enterprise?.name}}</p><p>发生时间 {{sf(detail.occurredAt)}} · {{detail.address||detail.organization?.name}}</p></div><div class="safety-case-tools"><el-button :icon="Download" :loading="exporting" @click="exportEvidence">导出证据包</el-button><el-dropdown v-if="!enterprise&&permission(session.user,'safety:emergency:dispatch')" @command="newTask"><el-button type="primary">发起任务⌄</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="EMERGENCY">发起应急</el-dropdown-item><el-dropdown-item command="RECTIFICATION">下达整改</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button v-if="nextAction" :loading="actionBusy" type="primary" plain @click="act">{{caseActionLabel(nextAction)}}</el-button></div></header><div class="safety-tabs"><button v-for="t in [['evidence','证据回溯'],['history','处置记录'],['tasks',`关联任务（${detail.tasks.length}）`]]" :key="t[0]" type="button" :aria-pressed="tab===t[0]" @click="tab=t[0]!;playing=false">{{t[1]}}</button></div><template v-if="tab==='evidence'"><div class="safety-evidence-grid"><AccidentVideoPlayer :key="`${selected.kind}:${selected.id}`" :videos="detail.videos" :cursor-time="cursor" :playing="playing" :speed="speed" :source-state="detail.videoState" @seek="cursor=Math.max(from,Math.min(to,$event))" @update:playing="playing=$event"/><section class="pm-evidence-map"><header><strong>同步轨迹</strong><span>蓝色事前 · 紫色事后</span></header><ProvinceMonitoringMap v-if="detail.track.length||Number.isFinite(detail.longitude)&&Number.isFinite(detail.latitude)" :key="`${selected.kind}:${selected.id}:${revision??'live'}`" :track="detail.track" :cursor-time="cursor" :incident-at="t0" :max-gap-seconds="10" :max-cursor-gap-seconds="5" :incident="Number.isFinite(detail.longitude)&&Number.isFinite(detail.latitude)?{longitude:detail.longitude,latitude:detail.latitude}:undefined" height="280px"/><div v-else class="safety-error"><span>{{detail.access.tracks?'当前窗口暂无可用定位，等待补传':'当前账号没有轨迹查询权限'}}</span></div><div class="pm-inline-facts"><span>速度 <b>{{number(currentFix?.speed,' km/h')}}</b></span><span>电量 <b>{{number(currentFix?.battery,'%')}}</b></span><span><b>{{currentFix?sl(currentFix.autonomousState):'此时无定位上报'}}</b></span></div></section></div><div class="safety-core"><header class="safety-core-head"><strong>核心证据窗口</strong><el-tag size="small" :type="statusTone(detail.completeness.state)">{{sl(detail.completeness.state)}} · 150秒</el-tag><span class="safety-muted">事前90秒 · 事后60秒</span><el-select v-model="revision" aria-label="证据版本" placeholder="当前归集证据" clearable @change="loadDetail()"><el-option v-for="r in detail.revisions" :key="r.id" :value="r.version" :label="`保全版本V${r.version} · ${sl(r.state)}`"/></el-select><el-button size="small" @click="playing=false;cursor=t0">跳到事发</el-button></header><div class="safety-window-split"><span>T−90s 事前90秒</span><span>T+60s 事后60秒</span></div><EvidenceTimeline v-model="cursor" v-model:playing="playing" v-model:speed="speed" :from="from" :to="to" :incident-at="t0" :videos="detail.videos" title="视频与轨迹同步回放" :disabled="!detail.track.length&&!detail.videos.some((v:any)=>v.state==='AVAILABLE')"/><div class="safety-axis" aria-label="150秒证据刻度"><span v-for="n in [0,1,2,3,4,5]" :key="n" :style="{left:`${n*20}%`}">{{sf(from+n*30000,true)}}{{n===3?' · T0':''}}</span></div><p class="safety-muted" style="margin:8px 0">录像覆盖：{{detail.completeness.videoComplete?'完整':'待补齐'}} · 轨迹记录：{{detail.completeness.trackComplete?'连续':'存在缺失'}}<template v-if="detail.completeness.state==='COLLECTING'"> · 事后60秒尚在采集中</template><template v-if="detail.trackTruncated"> · 轨迹超过10000点，仅展示部分记录</template></p><div class="safety-case-tools" style="max-width:none;justify-content:flex-start"><el-button v-if="canVideo" size="small" @click="openVideo">补充录像</el-button><el-button v-if="canHandle&&permission(session.user,'operation:trajectory:read')" size="small" :icon="ShieldCheck" :loading="actionBusy" @click="preserve">保全证据</el-button><span v-if="revision" class="safety-muted">正在查看保全版本V{{revision}}，补传不会覆盖此版本</span></div></div><MonitoringRuleEvidence v-if="detail.evidence?.rule||detail.evidence?.actual" :evidence="detail.evidence"/><div class="safety-case-bottom"><section><h4>关键事件</h4><table class="safety-compact-table"><thead><tr><th>时间</th><th>事件</th><th>类型</th></tr></thead><tbody><tr v-for="event in keyEvents" :key="event.id"><td><button @click="playing=false;cursor=Date.parse(event.occurredAt)">{{sf(event.occurredAt,true)}}</button></td><td>{{event.title}}</td><td>{{sl(event.type)}}</td></tr></tbody></table><p v-if="detail.related.length" class="safety-muted">关联记录：<el-button v-for="r in detail.related" :key="r.id" link type="primary" @click="choose(r)">{{sl(r.kind)}} {{r.businessNo}}</el-button></p></section><section><h4>处置进展</h4><ul class="safety-log"><li v-for="h in detail.history.slice(-4)" :key="h.id"><strong>{{sl(h.action)}} · {{h.actorName}}</strong><small>{{sf(h.createdAt)}}</small><p v-if="h.content">{{h.content}}</p></li><li v-if="!detail.history.length"><strong>{{sl(detail.status)}}</strong><small>{{sf(detail.createdAt)}} 登记</small><p>{{detail.description||detail.reason||'等待进一步核查'}}</p></li></ul></section></div></template><template v-else-if="tab==='history'"><section class="safety-section"><h4>事件经过</h4><p>{{detail.description||detail.reason||'尚无补充说明'}}</p></section><section v-if="detail.investigation" class="safety-section"><h4>调查情况</h4><p>{{detail.investigation}}</p></section><section v-if="detail.determination?.documentNo" class="safety-section"><h4>已登记认定结果</h4><p>{{detail.determination.authority}} · {{detail.determination.documentNo}} · {{sf(detail.determination.issuedAt)}}</p><p>{{detail.determination.result}}</p><SafetyMaterials :model-value="detail.determination.materials"/></section><section v-else-if="detail.responsibility" class="safety-section"><h4>历史认定登记</h4><p>{{detail.responsibility}}</p></section><section v-if="detail.disposalProgress||detail.recoveryNote||detail.rectification" class="safety-section"><h4>最新处置反馈</h4><p>{{detail.disposalProgress||detail.recoveryNote||detail.rectification}}</p></section><section class="safety-section"><h4>处置记录</h4><ul class="safety-log"><li v-for="h in detail.history" :key="h.id"><strong>{{sl(h.action)}} · {{h.actorName}}</strong><small>{{sf(h.createdAt)}}</small><p>{{h.content}}</p></li></ul><el-empty v-if="!detail.history.length" description="暂无新增处置记录" :image-size="50"/><el-button v-if="selected.kind==='OFFLINE'&&canHandle&&detail.status!=='RECOVERED'" @click="offlineReason">补充离线原因</el-button></section></template><section v-else class="safety-section"><h4>关联任务</h4><el-empty v-if="!detail.tasks.length" description="暂无关联任务" :image-size="55"/><table v-else class="safety-compact-table"><thead><tr><th>任务</th><th>类型</th><th>状态</th><th>期限</th><th>操作</th></tr></thead><tbody><tr v-for="task in detail.tasks" :key="`${task.taskType}:${task.id}`"><td>{{task.title}}<small class="safety-muted" style="display:block">{{task.businessNo}}</small></td><td>{{sl(task.taskType)}}</td><td>{{sl(task.status)}}</td><td>{{sf(task.dueAt)}}</td><td><el-button link type="primary" @click="openTask(task)">详情</el-button></td></tr></tbody></table></section></template><div v-else-if="!detailLoading" class="safety-error"><strong>选择事件，查看证据与处置进展</strong><span>事件视频、轨迹和关联任务会在这里展示</span></div></main></div></section>
<SafetyTaskEditor v-model="taskEditor" :source="detail?{...detail,kind:selected.kind,id:selected.id}:undefined" :default-type="taskDefault" @created="taskCreated"/><SafetyTaskDrawer v-model="taskOpen" :id="taskId" :task-type="taskType" @changed="refresh"/>
<el-dialog v-model="editor" title="登记安全事件" width="min(760px,95vw)" class="safety-editor" :close-on-click-modal="false" :before-close="()=>confirmClose('event')"><div v-if="editorError||optionsError" class="safety-inline-error" role="alert">{{editorError||optionsError}}<el-button v-if="optionsError" link @click="loadOptions">重新读取车辆</el-button></div><el-form label-position="top" class="safety-form-grid"><el-form-item label="事件类型" required><el-select v-model="eventForm.kind" aria-label="登记事件类型"><el-option v-if="permission(session.user,'safety:accident:report')" label="事故" value="ACCIDENT"/><el-option v-if="permission(session.user,'safety:alert:write')" label="告警" value="ALERT"/></el-select></el-form-item><el-form-item label="涉及车辆" required><el-select v-model="eventForm.vehicleId" filterable aria-label="事件车辆" @change="eventForm.longitude=undefined;eventForm.latitude=undefined"><el-option v-for="v in options.vehicles" :key="v.id" :label="`${v.name} · ${v.businessNo}`" :value="v.id"/></el-select></el-form-item><el-form-item label="事件名称" class="wide" required><el-input v-model="eventForm.title" maxlength="150" aria-label="事件名称"/></el-form-item><el-form-item label="发生时间" required><el-date-picker v-model="eventForm.occurredAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="事件发生时间"/></el-form-item><el-form-item label="等级"><el-select v-model="eventForm.level" aria-label="事件等级"><el-option v-for="level in ['LOW','MEDIUM','HIGH','CRITICAL']" :key="level" :label="sl(level)" :value="level"/></el-select></el-form-item><el-form-item v-if="eventForm.kind==='ACCIDENT'" label="事故类型"><el-select v-model="eventForm.accidentType" aria-label="事故类型"><el-option label="碰撞 / 剐蹭" value="COLLISION"/><el-option label="人员受伤" value="PERSON_INJURY"/><el-option label="财产损失" value="PROPERTY_DAMAGE"/><el-option label="车辆失控" value="LOSS_OF_CONTROL"/><el-option label="其他" value="OTHER"/></el-select></el-form-item><el-form-item v-else label="告警类型"><el-select v-model="eventForm.alertType" aria-label="告警类型"><el-option label="人工上报" value="MANUAL_REPORT"/><el-option label="车辆故障" value="VEHICLE_FAULT"/><el-option label="自动驾驶异常" value="AUTONOMOUS_ABNORMAL"/><el-option label="其他" value="OTHER"/></el-select></el-form-item><el-form-item v-if="eventForm.kind==='ACCIDENT'" label="伤亡人数"><el-input-number v-model="eventForm.casualties" :min="0" :max="999" aria-label="伤亡人数"/></el-form-item><el-form-item label="事发经度" required><el-input-number v-model="eventForm.longitude" :min="-180" :max="180" :precision="6" :controls="false" aria-label="事发经度"/></el-form-item><el-form-item label="事发纬度" required><el-input-number v-model="eventForm.latitude" :min="-90" :max="90" :precision="6" :controls="false" aria-label="事发纬度"/></el-form-item><div class="wide" style="margin-bottom:14px"><el-button :disabled="!eventForm.vehicleId" @click="lastLocation">引用车辆最后上报位置</el-button><span class="safety-muted">请按实际事发位置核对坐标</span></div><el-form-item label="事发地点" class="wide"><el-input v-model="eventForm.address" aria-label="事发地点"/></el-form-item><el-form-item label="事件经过" class="wide" required><el-input v-model="eventForm.description" type="textarea" :rows="4" aria-label="事件经过" maxlength="5000" show-word-limit/></el-form-item></el-form><template #footer><el-button :disabled="editorSaving" @click="confirmClose('event')">取消</el-button><el-button type="primary" :loading="editorSaving" @click="saveEvent">登记事件</el-button></template></el-dialog>
<el-dialog v-model="videoDialog" title="补充事件录像" width="min(700px,95vw)" class="safety-editor" :close-on-click-modal="false" :before-close="()=>confirmClose('video')"><div v-if="videoError" class="safety-inline-error" role="alert">{{videoError}}</div><el-form label-position="top" class="safety-form-grid"><el-form-item label="录像来源" class="wide"><el-radio-group v-model="videoForm.mode"><el-radio-button value="upload">上传录像</el-radio-button><el-radio-button value="link">关联来源地址</el-radio-button></el-radio-group></el-form-item><div v-if="videoForm.mode==='upload'" class="wide" style="margin-bottom:18px"><SafetyMaterials v-model="videoFiles" :enterprise-id="detail?.enterpriseId" video-only editable @busy="uploading=$event"/><p v-if="videoFiles.length>1" class="safety-muted">本次关联第一份录像，其他通道请分别提交</p></div><el-form-item v-else label="录像地址" required class="wide"><el-input v-model="videoForm.url" aria-label="录像地址" placeholder="HTTP(S)来源地址"/></el-form-item><el-form-item label="录像名称"><el-input v-model="videoForm.name" aria-label="录像名称" maxlength="120"/></el-form-item><el-form-item label="摄像头通道"><el-select v-model="videoForm.channel" aria-label="摄像头通道"><el-option v-for="v in [['FRONT','前视'],['BACK','后视'],['LEFT','左侧'],['RIGHT','右侧'],['SIDE','侧视'],['UNKNOWN','其他通道']]" :key="v[0]" :value="v[0]" :label="v[1]"/></el-select></el-form-item><el-form-item label="录像开始时间" required><el-date-picker v-model="videoForm.startedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="录像开始时间"/></el-form-item><el-form-item label="录像结束时间" required><el-date-picker v-model="videoForm.endedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="录像结束时间"/></el-form-item><el-form-item label="来源说明" class="wide"><el-input v-model="videoForm.source" aria-label="录像来源说明" maxlength="120"/></el-form-item></el-form><p class="safety-muted">按录像实际起止时间填写；补传不会覆盖已保全的证据版本。</p><template #footer><el-button :disabled="videoBusy||uploading" @click="confirmClose('video')">取消</el-button><el-button type="primary" :loading="videoBusy" :disabled="uploading" @click="submitVideo">关联录像</el-button></template></el-dialog>
<el-dialog v-model="determinationDialog" title="登记事故认定结果" width="min(720px,95vw)" class="safety-editor" :close-on-click-modal="false" :before-close="()=>confirmClose('determination')"><div v-if="determinationError" class="safety-inline-error" role="alert">{{determinationError}}</div><el-form label-position="top" class="safety-form-grid"><el-form-item label="认定机关" required><el-input v-model="determinationForm.authority" aria-label="认定机关" maxlength="150"/></el-form-item><el-form-item label="文书编号" required><el-input v-model="determinationForm.documentNo" aria-label="认定文书编号" maxlength="100"/></el-form-item><el-form-item label="出具时间" required><el-date-picker v-model="determinationForm.issuedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="文书出具时间"/></el-form-item><el-form-item label="认定结果" required class="wide"><el-input v-model="determinationForm.result" type="textarea" :rows="4" aria-label="认定结果" maxlength="5000"/></el-form-item><el-form-item label="认定文书" required class="wide"><SafetyMaterials v-model="determinationFiles" :enterprise-id="detail?.enterpriseId" editable @busy="uploading=$event"/></el-form-item></el-form><template #footer><el-button :disabled="videoBusy||uploading" @click="confirmClose('determination')">取消</el-button><el-button type="primary" :loading="videoBusy" :disabled="uploading" @click="submitDetermination">登记结果</el-button></template></el-dialog>
</section></template>
